let keys = dynamic(["user_mgmt_useradd", "user_mgmt_userdel", "user_mgmt_adduser", "user_mgmt_deluser"]);
let timeDifmin = 60;
// getting event ids
let auditEventIds = ASimLinuxAuditdSyslogV01(disabled=false)
    | where key in (keys)
    | project auditEventId;
// gettings events by their event id
let auditEvents = ASimLinuxAuditdSyslogV01(disabled=false)
    | where auditEventId in (auditEventIds);
// deleting user
let UserDeletionEvents = auditEvents
    | where AuditEventType == 'EXECVE' and (a0 == 'deluser' or a0 == 'userdel')
    | extend _deluser_raw_parsedData = iif(a0 == 'deluser',
        // getting username and group from cmdline
        set_union(
            extract_all(@"deluser\s(?:(\w+\S+)\s(\w+\S+)|(\w+\S+))", allArgs)[0],
            extract_all(@"deluser.+(\s(\w+\S+)\s(\w+\S+)$)?\s(\w+\S+)\s(\w+\S+)$|\s(\w+\S+)$", allArgs)[0]
        ),
        dynamic(null)),
        _userdel_extractedUser = iif(a0 == 'userdel',tostring(split(allArgs, " ")[-1]),"")
    // getting username
    | extend deletedUser = iif(
        a0 == 'deluser',
        iff(
            isnotempty(_deluser_raw_parsedData) and array_length(_deluser_raw_parsedData) == 1,
            tostring(_deluser_raw_parsedData[0]),
            "" 
        ),
        iff(a0 == 'userdel',_userdel_extractedUser,"")
    )
    | where isnotempty(deletedUser)
    | project
        DeletedAt = TimeGenerated,
        deletedUser,
        Dvc,
        auditEventId,
        SyslogMessage;
// creating user
let UserCreationEvents = auditEvents
    | where AuditEventType == 'EXECVE' and (a0 == 'adduser' or a0 == 'useradd')
    | extend addedUser = tostring(split(allArgs, " ")[-1])
    | project
        CreatedAt = TimeGenerated,
        addedUser,
        Dvc,
        auditEventId,
        SyslogMessage;
UserCreationEvents
    | join kind=inner (UserDeletionEvents) on $left.addedUser == $right.deletedUser and $left.Dvc == $right.Dvc
    | where datetime_diff('minute', CreatedAt, DeletedAt) <= timeDifmin
    | project Dvc, 
        Username=addedUser, 
        CreatedAt, 
        CreateAuditEventId=auditEventId, 
        DeletedAt,
        DeleteAuditEventId=auditEventId1;

let SuspDirOpsCount = 3;
// declare directories here
let dirsToMonitor = dynamic(['/tmp']);
let CreateEventIds = ASimLinuxAuditdSyslogV01(false)
    | where syscall has_any (2, 257, 85, 83, 258, 89, 267, 86, 265)
    | project auditEventId;
let DeleteEventIds = ASimLinuxAuditdSyslogV01(false)
    | where syscall has_any (87, 263, 84)
    | project auditEventId;
let CreateEvents = ASimLinuxAuditdSyslogV01(false)
    | where auditEventId in (CreateEventIds)
    | where isnotempty(name) and 
        name has_any(dirsToMonitor)
    | project TimeGenerated, auditEventId, Dvc, name;
let DeleteEvents = ASimLinuxAuditdSyslogV01(false)
    | where auditEventId in (DeleteEventIds)
    | where isnotempty(name) and 
        name has_any(dirsToMonitor)
    | project TimeGenerated, auditEventId, Dvc, name;
CreateEvents
    | join kind=inner (DeleteEvents) on $left.name == $right.name and $left.Dvc == $right.Dvc
    | where TimeGenerated <= TimeGenerated1
    | summarize SuspDirOps = count(), CreatedAt=avg(TimeGenerated), DeletedAt=avg(TimeGenerated1)  by Dvc
    | project CreatedAt, DeletedAt, Dvc, SuspDirOps

