let FirewallChangesCount = 3;
let keys = dynamic(["iptables_exec", 
    "nftables_exec", 
    "firewall-cmd_exec", 
    "ufw_exec"]);
let excludedArgs = dynamic([
    'status',
    '-L',
    'list',
    '--get-active-zones', 
    '--list-all-zones',
    '--list-all',
    '--list-services',
    '--list-ports',
