let timeDifmin = 60;
// declare your groups here
let forbidGrps = dynamic(["sudo","wheel"]);
let keys = dynamic(["user_mgmt_useradd","user_mgmt_adduser","user_mgmt_usermod", "user_mgmt_userdel", "user_mgmt_deluser"]);
// getting event ids
let auditEventIds = ASimLinuxAuditdSyslogV01(disabled=false)
    | where key in (keys)
    | project auditEventId;
// gettings events by their event id
let auditEvents = ASimLinuxAuditdSyslogV01(disabled=false)
    | where auditEventId in (auditEventIds);
// getting adduser and usermod -aG events
let AddAddUserEvents = auditEvents
    | where AuditEventType == 'EXECVE'
    | extend raw = iif((a0 == 'adduser' and array_length(split(allArgs, " ")) == 3),extract_all(@"adduser\s(\w+\S+)\s([\w\S,]+)",allArgs)[0],dynamic(null))
    | extend Username = tostring(raw[0])
    | extend Group = split(array_slice(raw,1,2)[0],',')
    | where isnotempty(Username)
    | mv-expand Group
    | extend Group = tostring(Group)
    | where Group has_any (forbidGrps)
    | project CreatedAt=TimeGenerated, Dvc, Username, Group, auditEventId;    
let AddAddUserEvents1 = auditEvents
    | where AuditEventType == 'EXECVE'
    | extend raw = iif((a0 == 'adduser' and allArgs contains "--ingroup"),extract_all(@"adduser.+\-\-ingroup\s([\w\S,]+)\s(\w+\S+)",allArgs)[0],dynamic(null))
    | extend Username = tostring(raw[1])
    | extend Group = split(array_slice(array_reverse(raw), 1,2)[0],',')
    | where isnotempty(Username)
    | mv-expand Group
    | extend Group = tostring(Group)
    | where Group has_any (forbidGrps)
    | project CreatedAt=TimeGenerated, Dvc, Username, Group, auditEventId; 
let AddUsermodEvents = auditEvents
    | where AuditEventType == 'EXECVE'
    | extend raw = iif(a0 == 'usermod',extract_all(@"usermod.+(?i)(?:-a.+-g|-aG)\s([\w\S,]+).*\s(\w+\S+)$",allArgs)[0],dynamic(null))
    | extend Username = tostring(raw[1])
    | extend Group = split(array_slice(array_reverse(raw), 1,2)[0],',')
    | where isnotnull(Username)
    | mv-expand Group
    | where Group has_any (forbidGrps)
    | extend Group = tostring(Group)
    | project CreatedAt=TimeGenerated, Dvc, Username, Group, auditEventId; 
// uniting addition result
let AddUserUnion = union isfuzzy=true AddAddUserEvents, AddAddUserEvents1, AddUsermodEvents;
// projecting required data
AddUserUnion
    | project Dvc, 
        Username,
        Group, 
        CreatedAt, 
        CreateAuditEventId=auditEventId;

